package com.crms.controller;import com.crms.enums.*;import com.crms.repository.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('ADMIN','PLACEMENT_OFFICER')") public class AdminController{private final UserRepository users;private final JobRepository jobs;private final ApplicationRepository apps;public AdminController(UserRepository u,JobRepository j,ApplicationRepository a){users=u;jobs=j;apps=a;}@GetMapping("/dashboard")public Map<String,Long> dashboard(){return Map.of("users",users.count(),"jobs",jobs.count(),"applications",apps.count(),"selected",apps.countByStatus(ApplicationStatus.SELECTED));}@GetMapping("/users")public List<Map<String,Object>> allUsers(){return users.findAll().stream().map(u->Map.<String,Object>of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole().name())).toList();}@GetMapping("/jobs")public List<com.crms.entity.JobPosting> allJobs(){return jobs.findAll();}@GetMapping("/applications")public List<com.crms.entity.Application> allApps(){return apps.findAll();}@GetMapping("/placements/statistics")public Map<String,Long> stats(){return Map.of("total_users",users.count(),"open_jobs",jobs.findByStatus(JobStatus.OPEN).stream().count(),"applications",apps.count(),"selected",apps.countByStatus(ApplicationStatus.SELECTED));}}
